badPacket(p=>{p.original.source.files.entries[0].content.extra=true});badPacket(p=>{p.original.fileResult.files[1].content=copy(p.original.source.files.entries[0].content)})
badPacket(p=>{p.original.source.files.entries[0].content=base.original.source.files.entries[0].content});badPacket(p=>{p.original.fileResult.files[1].content=null})
badPacket(p=>{const original=copy(base.original),ids=p.original.source.files.entries[0].content.evidenceIds.slice().reverse(),text=ids.map(id=>p.claimEvidence.items.find(item=>item.id===id).text).join('');p.original.source.files.entries[0].content={evidenceIds:ids};p.original.fileResult.files[0].content={evidenceIds:ids};original.source.files.entries[0].content=text;original.fileResult.files[0].content=text;original.fileResult.outputDigest=sha256({answer:original.fileResult.answer,files:original.fileResult.files});p.original.fileResult.outputDigest=original.fileResult.outputDigest;p.originalDigest=sha256(original)})
badOriginal(p=>{p.task=copy(p.source)});badOriginal(p=>{delete p.source});badOriginal(p=>{p.source.files.outputKind='chat'});badOriginal(p=>{p.source.files.entries[0].path='../input.txt'})
badOriginal(p=>{p.fileResult.files.reverse();p.fileResult.outputDigest=sha256({answer:p.fileResult.answer,files:p.fileResult.files})});badOriginal(p=>{p.fileResult.outputDigest=sha256('wrong')});badOriginal(p=>{p.fileResult.files[1].content=null;p.fileResult.outputDigest=sha256({answer:p.fileResult.answer,files:p.fileResult.files})})
badOriginal(p=>{p.fileResult.extra=true})
badEvidence(e=>{e.items.push(copy(e.items[0]))});badEvidence(e=>{e.schemaVersion='tianwen.claim-evidence.v1'});badEvidence(e=>{e.extra=true});badEvidence(e=>{e.items[0].extra=true})
badEvidence(e=>{e.items[0].id='tool-90'});badEvidence(e=>{e.items.find(item=>item.fileStage==='initial').role='answer'});badEvidence(e=>{e.items.find(item=>item.fileStage==='initial').filePath='output.txt'})
badEvidence(e=>{e.items.find(item=>item.fileStage==='initial').text='wrong'});badEvidence(e=>{delete e.items.find(item=>item.fileStage==='initial').fileStage});badEvidence(e=>{e.items.find(item=>item.fileStage==='final').fileStage='initial'})
for(const malformed of [undefined,()=>{},NaN,Infinity,'\ud800'])badOriginal(p=>{p.extra.malformed=malformed})
badOriginal(p=>{p.extra.loop=p});badOriginal(p=>{p.extra.large='x'.repeat(512*1024)})
badOriginal(p=>{p.extra.array=Array(2)});badOriginal(p=>{p.extra.array=[1];p.extra.array.extra=1});badOriginal(p=>{p.extra[Symbol('hidden')]=1});badOriginal(p=>{Object.defineProperty(p.extra,'hidden',{value:1,enumerable:false})})
